contracts/vaults/USD1/sUSD1PlusVault.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {EIP712Upgradeable} from "@openzeppelin/contracts-upgradeable/utils/cryptography/EIP712Upgradeable.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

import {Vault} from "../Vault.sol";
import {YieldType} from "../../intf/IVault.sol";
import {IUSD1PlusVault} from "./IUSD1PlusVault.sol";

contract sUSD1PlusVault is
    UUPSUpgradeable,
    EIP712Upgradeable,
    Vault
{
    using EnumerableSet for EnumerableSet.AddressSet;
    // users deposit usd1 to the vault, and get a pending shares waiting for KYT
    event PendingShares(address indexed user, uint128 indexed period, uint256 shares);
    // users confirm the shares after KYT passed
    event ConfirmShares (address indexed user, bytes32 indexed txHash, uint128 indexed period, uint256 shares);
    // users refund the shares after KYT failed
    event RefundShares  (address indexed user, bytes32 indexed txHash, uint128 indexed period, uint256 shares);
    // role setted
    event RoleSetted(bytes32 indexed role, address indexed account, address indexed sender, bool isGrant);
    // minter mint
    event MinterMint(address indexed to, uint256 sharesAmount, address sender);
    // burner burn
    event BurnerBurn(address indexed from, uint256 sharesAmount, address sender);
    // pendle deposit
    event DirectDeposit(
        address indexed user,
        uint128 period,
        address underlyingToken,
        uint256 underlyingAmount,
        uint256 sharesAmount,
        uint256 unitNav,
        uint256 timestamp
    );
    // BN wallet supply
    event Supply(
        address indexed user,
        uint128 period,
        address underlyingToken,
        uint256 underlyingAmount,
        uint256 sharesAmount,
        uint256 unitNav,
        uint256 timestamp
    );

    event Unsupply(
        uint128 indexed requestId,
        address indexed sender,
        uint256 sharesAmount,
        uint256 timestamp
    );

    bytes32 public constant CONFIRM_SHARE = keccak256("ConfirmShare(uint128 period,bytes32 txHash,address user,uint256 sharesAmount)");
    bytes32 public constant REFUND_SHARE = keccak256("RefundShare(uint128 period,bytes32 txHash,address user,uint256 sharesAmount)");

    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");  // 0x01
    bytes32 public constant BURNER_ROLE = keccak256("BURNER_ROLE");  // 0x02
    bytes32 public constant DEPOSIT_ROLE = keccak256("DEPOSIT_ROLE"); // 0x04

    mapping(address => mapping(uint128 => uint256)) public pendingShares; // user -> period -> pending shares
    mapping(address => bool) public signers; // signer -> is signer
    mapping(bytes32 => bool) public confirmedTx; // txHash -> is confirmed
    mapping(bytes32 => bool) public refundedTx; // txHash -> is refunded

    // address of the USD1+ vault
    IUSD1PlusVault public usd1PlusVault;

    // record the confirmed shares of the user of a period,
    // because the user can not request withdraw the confirmed shares in the same period,
    // the confirmed shares must stay in the vault for at least next period
    mapping(address => mapping(uint128 => uint256)) public confirmedShares; // user -> period -> confirmed shares

    // add roles for minter and burner for chainlink ccip @Sep. 3, 2025
    // mint role:  0x01, burner role: 0x02, depositor role: 0x04
    mapping(address => uint256) public roles; // account -> role
    // ----------- ADD STATE VARIABLES -----------
    // -------------------------------------------

    modifier onlyMinter() {
        require(roles[msg.sender] & uint256(0x01) == uint256(0x01), "minter only");
        _;
    }
    modifier onlyBurner() {
        require(roles[msg.sender] & uint256(0x02) == uint256(0x02), "burner only");
        _;
    }
    modifier onlyDepositor() {
        require(roles[msg.sender] & uint256(0x04) == uint256(0x04), "depositor only");
        _;
    }

    constructor() {
        _disableInitializers();
        yieldType = YieldType.Custody;
    }

    // @dev initialize the usd1 vault
    // @param name_ the name of the vault
    // @param symbol_ the symbol of the vault
    // @param underlying_ the underlying asset of the vault
    // @param portfolios_ the portfolios of the vault
    // @param weights_ the weights of the portfolios
    // @param cedefiManager_ the cedefi manager of the vault
    function initialize(
        string calldata name_,
        string calldata symbol_,
        address cedefiManager_
    ) public initializer {
        require(cedefiManager_ != address(0), "Invalid cedefi manager");

        __EIP712_init("USD1Vault", "1.0");
        __UUPSUpgradeable_init();
        __ERC20_init(name_, symbol_);

        cedefiManager = cedefiManager_;

        settlementPeriod = 1;
        transferable = true;
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyManager {}

    receive() external payable {
        revert("Not allowed native token");
    }

    // @dev set underlying token
    function setUnderlying(address _underlying) public onlyManager {
        require(_underlying != address(0), "invalid underlying");
        underlying = _underlying;
    }

    // @dev set the signer
    function setSigner(address[] memory signers_, bool[] memory isSigners_) public onlyManager {
        require(signers_.length == isSigners_.length, "mismatch length of signers");

        for (uint256 i = 0; i < signers_.length; i++) {
            require(signers_[i] != address(0), "zero signer");
            signers[signers_[i]] = isSigners_[i];
        }
    }

    // @dev set the minter role
    function setRole(bytes32 role, address account, bool isGrant) public onlyManager {
        if (role == MINTER_ROLE) {
            roles[account] = isGrant ? roles[account] | uint256(0x01) : roles[account] & ~uint256(0x01);
        } else if (role == BURNER_ROLE) {
            roles[account] = isGrant ? roles[account] | uint256(0x02) : roles[account] & ~uint256(0x02);
        } else if (role == DEPOSIT_ROLE) {
            roles[account] = isGrant ? roles[account] | uint256(0x04) : roles[account] & ~uint256(0x04);
        } else {
            revert("invalid role");
        }
        emit RoleSetted(role, account, msg.sender, isGrant);
    }

    // to handle the depoisted underlying asset
    function onDepositUnderlying(address from, address underlyingToken, uint256 underlyingAmount)
        internal
        override
        returns (uint256 sharesAmount, uint256 unitNav)
    {
        // transfer the underlying asset to the ceff wallet
        address ceffWallet = _portfolios.at(0);
        IERC20 assetToken = IERC20(underlyingToken);
        // 根据Ceffu要求, 转入Ceffu的from地址需要加白, 所以先将token转到合约, 再转到ceffu
        SafeERC20.safeTransferFrom(assetToken, from, address(this), underlyingAmount);
        SafeERC20.safeTransfer(assetToken, ceffWallet, underlyingAmount);

        uint256 alignedAmount = alignDepositAmount(underlyingAmount, underlyingToken);
        require(alignedAmount >= minDepositAmount, "amount too small");

        // calculate the shares amount
        unitNav = getUnitNav(settlementPeriod);
        require(unitNav > 0, "oops: zero unit nav");
        sharesAmount = alignedAmount * Precision / unitNav;

        // calculate the pending shares
        pendingShares[from][settlementPeriod] += sharesAmount;

        // emit the event
        emit PendingShares(from, settlementPeriod, sharesAmount);
    }
    // to handle the withdrawed underlying asset
    function onWithdrawUnderlying(address to, uint256 underlyingAmount)
        internal
        override
    {
        sendUnderlying(to, underlyingAmount);
    }

    // @dev confirm the shares
    // while the deposit passed KYT, then the user can confirm the shares
    function confirmShare(
        uint128 period,
        bytes32 txHash,
        uint256 sharesAmount,
        bytes memory signature
    )
        public
        whenNotPaused
    {
        require(sharesAmount > 0, "Invalid shares amount");
        require(pendingShares[msg.sender][period] >= sharesAmount, "not enough shares amount");
        require(!confirmedTx[txHash], "tx already confirmed");
        require(!refundedTx[txHash], "tx already refunded");

        // verify the signature
        bytes32 hash = _hashTypedDataV4(keccak256(abi.encode(
            CONFIRM_SHARE,
            period,
            txHash,
            msg.sender,
            sharesAmount
        )));
        address signer = ECDSA.recover(hash, signature);
        require(signers[signer], "Invalid signer");
        confirmedTx[txHash] = true;

        // sub the pending shares
        pendingShares[msg.sender][period] -= sharesAmount;
        // add the confirmed shares
        confirmedShares[msg.sender][period] += sharesAmount;

        // mint the shares
        _mint(msg.sender, sharesAmount);

        // emit the event
        emit ConfirmShares(msg.sender, txHash, period, sharesAmount);
    }
    // @dev refund the shares
    // if the deposit failed KYT, then the user can refund the shares
    // just burn the shares, the underlying asset will be returned to the user by Ceffu automatically
    function refundShare(
        uint128 period,
        bytes32 txHash,
        uint256 sharesAmount,
        bytes memory signature
    )
        public
        whenNotPaused
    {
        require(pendingShares[msg.sender][period] >= sharesAmount, "not enough shares amount");
        require(!refundedTx[txHash], "tx already refunded");
        require(!confirmedTx[txHash], "tx already confirmed");

        // verify the signature
        bytes32 hash = _hashTypedDataV4(keccak256(abi.encode(
            REFUND_SHARE,
            period,
            txHash,
            msg.sender,
            sharesAmount
        )));
        address signer = ECDSA.recover(hash, signature);
        require(signers[signer], "Invalid signer");
        refundedTx[txHash] = true;
        // sub the pending shares
        pendingShares[msg.sender][period] -= sharesAmount;

        // emit the event
        emit RefundShares(msg.sender, txHash, period, sharesAmount);
    }

    // @dev get the details of the balance
    struct BalanceDetails {
        uint256 totalShares;      // total shares of the user
        uint256 frozenShares;    // frozen shares of the user
        uint256 withdrawingShares; // withdrawing shares of the user
    }
    function getBalanceDetails(address user) public view returns (BalanceDetails memory) {
        BalanceDetails memory details;

        details.totalShares = balanceOf(user);
        details.frozenShares = frozenShares[user];
        details.withdrawingShares = getOngoingWithdrawShares(user);

        return details;
    }

    // @dev get current unit nav
    // @param period the period to get the unit nav, period should gte 1
    function getCurrentUnitNav() public view returns (uint256) {
        return getUnitNav(settlementPeriod);
    }

    // @dev method mint for chainlink CCIP
    function mint(address to, uint256 sharesAmount) public onlyMinter {
        _mint(to, sharesAmount);
        emit MinterMint(to, sharesAmount, msg.sender);
    }

    // @dev method burn for chainlinkCCIP
    function burn(uint256 sharesAmount) public {
        require(sharesAmount <= getUsableShares(msg.sender), "not enough shares amount");
        _burn(msg.sender, sharesAmount);
    }

    // @dev method burnFrom for chainlink CCIP
    function burnFrom(address from, uint256 sharesAmount) public onlyBurner {
        require(sharesAmount <= getUsableShares(from), "not enough shares amount");
        _burn(from, sharesAmount);
        emit BurnerBurn(from, sharesAmount, msg.sender);
    }

    // @dev internal method to supply the shares
    function _supply(address underlyingToken, uint256 underlyingAmount) internal returns (uint256, uint256) {
        require(acceptUnderlying[underlyingToken] || underlyingToken == underlying);
                // transfer the underlying asset to the ceff wallet
        address ceffWallet = _portfolios.at(0);
        IERC20 assetToken = IERC20(underlyingToken);
        SafeERC20.safeTransferFrom(assetToken, msg.sender, ceffWallet, underlyingAmount);

        uint256 alignedAmount = alignDepositAmount(underlyingAmount, underlyingToken);
        require(alignedAmount >= minDepositAmount, "deposit amount too small");

        // calculate the shares amount
        uint256 unitNav = getUnitNav(settlementPeriod);
        require(unitNav > 0, "oops: zero unit nav");
        uint256 sharesAmount = alignedAmount * Precision / unitNav;

        // mint the shares
        _mint(msg.sender, sharesAmount);

        return (sharesAmount, unitNav);
    }

    // @dev method for Pendle or someone else to deposit without KYT.
    // just composit the deposit and confirm function.
    function directDeposit(address underlyingToken, uint256 underlyingAmount) public onlyDepositor {
        (uint256 sharesAmount, uint256 unitNav) = _supply(underlyingToken, underlyingAmount);
        // emit the event
        emit DirectDeposit(msg.sender, settlementPeriod, underlyingToken, underlyingAmount, sharesAmount, unitNav, block.timestamp);
    }

    // @dev method for BN wallet
    function supply(address underlyingToken, uint256 underlyingAmount) public {
        (uint256 sharesAmount, uint256 unitNav) = _supply(underlyingToken, underlyingAmount);
        // emit the event
        emit Supply(msg.sender, settlementPeriod, underlyingToken, underlyingAmount, sharesAmount, unitNav, block.timestamp);
    }

    // @dev method for BN wallet to unsupply the shares
    function unsupply(uint256 sharesAmount) public {
        uint128 requestId = _doRequestWithdraw(sharesAmount);
        emit Unsupply(requestId, msg.sender, sharesAmount, block.timestamp);
    }
}

contracts/vaults/Vault.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import {IVault, YieldType} from "../intf/IVault.sol";
import {VaultBase} from "./VaultBase.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

abstract contract Vault is
    ERC20Upgradeable,
    PausableUpgradeable,
    VaultBase,
    IVault
{
    address public constant NATIVE_TOKEN = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    using EnumerableSet for EnumerableSet.AddressSet;
    using EnumerableSet for EnumerableSet.UintSet;

    event AddBlacklists(address[] users);
    event RemoveBlacklists(address[] users);
    event FreezeShares(address account, uint256 shares);
    event UnfreezeShares(address account, uint256 shares);

    event SetUnitNav(uint128 settlementPeriod, uint256 unitNav);
    event SetMinDepositAmount(uint256 amount);
    event SetMinWithdrawAmount(uint256 amount);
    event UpdatePortfolios(address[] portfolios, uint256[] weights);
    event SetTransferable(bool transferable);
    event SetAcceptUnderlying(address[] underlyingTokens, bool[] accepts);
    event ResetUnitNav(uint128 period, uint256 unitNav);

    // @dev while users deposit underlying asset, how to allocate the asset to different portfolios,
    //  for different yield type vault, it should be implemented by different way
    function onDepositUnderlying(address from, address underlyingToken, uint256 underlyingAmount) internal virtual returns (uint256 sharesAmount, uint256 unitNav);
    // @dev while users withdraw underlying asset, how to withdraw the asset from different portfolios,
    //    implement by different way for different yield type vault
    function onWithdrawUnderlying(address from, uint256 underlyingAmount) internal virtual;

    function updatePortfolios(address[] memory  portfolios_, uint256[] memory weights_) public onlyManager {
        require(portfolios_.length == weights_.length, "mismatch length of portfolios and weights");

        // remove old portfolios
        address[] memory oldPortfolios = EnumerableSet.values(_portfolios);
        for (uint256 i = 0; i < oldPortfolios.length; i++) {
            delete portfolioWeights[oldPortfolios[i]];
            _portfolios.remove(oldPortfolios[i]);
        }

        // add new portfolios
        uint256 totalWeight;
        uint256 len = portfolios_.length;
        for (uint256 i = 0; i < len; ) {
            bool success = _portfolios.add(portfolios_[i]);
            require(success, "Duplicated portfolio");

            portfolioWeights[portfolios_[i]] = weights_[i];
            totalWeight += weights_[i];

            unchecked { i++; }
        }
        require(totalWeight == Precision, "Invalid total weight");
        emit UpdatePortfolios(portfolios_, weights_);
    }

    // @dev to set the unit NAV of the current period
    // while the unit nav settled, all these withdraw reqeusts are settled,
    // then no matter they finish or not finish the withdraw,
    // all the requested shares stop yielding,
    // and the totalSupply() MUST substract these shares.
    //
    // CAUTION: for the same period, this method can only be called once
    function setUnitNav(uint256 unitNav) external onlyManager {
        uint128 index = settlementPeriod;
        require(periodUnitNav[index] == 0, "period settled already");
        // FIXME: should do this check??????
        require(unitNav != 0, "invalid unit nav");

        periodUnitNav[index] = unitNav;
        unsettledWithdrawShares += periodWithdrawShares[index];

        ++settlementPeriod;

        emit SetUnitNav(index, unitNav);
    }

    // @dev reset the unit nav of the target period
    // it only reset the unit nav of the target period, but not change the settlementPeriod
    // ONLY for mis setting the unit nav of the target period
    function resetUnitNav(uint128 period, uint256 unitNav) external onlyManager {
        require(period < settlementPeriod, "period not settled");
        require(unitNav > 0, "invalid unit nav");

        periodUnitNav[period] = unitNav;

        emit ResetUnitNav(period, unitNav);
    }

    // @dev set min deposit amount
    function setMinDepositAmount(uint256 amount) external onlyManager {
        require(amount > 0, "invalid amount");
        minDepositAmount = amount;

        emit SetMinDepositAmount(amount);
    }

    // @dev set min withdraw amount
    function setMinWithdrawAmount(uint256 amount) external onlyManager {
        require(amount > 0, "invalid amount");
        minWithdrawAmount = amount;

        emit SetMinWithdrawAmount(amount);
    }

    // @dev add blacklisted user
    function addBlacklist(address[] calldata users) external onlyManager {
        uint256 len = users.length;
        for (uint256 i = 0; i < len; ) {
            blacklisted[users[i]] = true;
            unchecked { i++; }
        }

        emit AddBlacklists(users);
    }

    // @dev remove blacklisted user
    function removeBlacklist(address[] calldata users) external onlyManager {
        uint256 len = users.length;
        for (uint256 i = 0; i < len; ) {
            delete blacklisted[users[i]];
            unchecked { i++; }
        }

        emit RemoveBlacklists(users);
    }

    // @dev freeze the shares of the target address
    function freezeShares(address account, uint256 shares) external onlyManager {
        uint256 leftShares = getUsableShares(account);
        if (shares > leftShares) {
            shares = leftShares;
        }

        frozenShares[account] += shares;
        emit FreezeShares(account, shares);
    }

    // @dev unfreeze the shares of the target address
    function unfreezeShares(address account, uint256 shares) external onlyManager {
        uint256 freezed = frozenShares[account];
        if (shares > freezed) {
            shares = freezed;
        }

        frozenShares[account] -= shares;
        emit UnfreezeShares(account, shares);
    }

    // @dev to pause the vault
    function pause() external onlyManager {
        _pause();
    }

    // @dev to unpause the vault
    function unpause() external onlyManager {
        _unpause();
    }

    // @dev set the accept underlying token
    // these tokens can deposit to the vault, but while withdraw, only the underlying token provide
    function setAcceptUnderlying(address[] calldata underlyingTokens, bool[] calldata accepts) external onlyManager {
        uint256 len = underlyingTokens.length;
        require(len == accepts.length, "length mismatch");
        for (uint256 i; i < len; ) {
            acceptUnderlying[underlyingTokens[i]] = accepts[i];
            unchecked { i++; }
        }

        emit SetAcceptUnderlying(underlyingTokens, accepts);
    }

    // @dev transfer from/to underlying token
    function sendUnderlying(address to, uint256 underlyingAmount) internal {
        if (underlying == NATIVE_TOKEN) {
            (bool success, bytes memory data) = to.call{value: underlyingAmount}("");
            require(success, string(data));
        } else {
            IERC20 underlyingToken = IERC20(underlying);
            SafeERC20.safeTransfer(underlyingToken, to, underlyingAmount);
        }
    }

    // @dev set the shares transferable or not
    function setTransferable(bool transferable_) external onlyManager {
        require(transferable != transferable_, "same transferable");
        transferable = transferable_;
        emit SetTransferable(transferable_);
    }

    // @dev total supply of shares, it should substract the withdrew shares of unsettled withdraw requests
    function totalSupply()
        public
        virtual
        view
        override(IERC20, ERC20Upgradeable)
        returns (uint256)
    {
        uint256 rawSupply = super.totalSupply();
        return rawSupply - unsettledWithdrawShares;
    }

    // @dev transfer shares token to the target address, should check the freezed shares
    function transfer(address recipient, uint256 amount)
        public
        virtual
        override(IERC20, ERC20Upgradeable)
        whenNotPaused
        notBlacklisted
        returns (bool)
    {
        require(transferable, "Not transferable");
        require(getUsableShares(msg.sender) >= amount, "Insufficient balance");
        return super.transfer(recipient, amount);
    }

    // @dev ban transferFrom
    //  not allowed approve someone else to transfer shares
    function transferFrom(address from, address to, uint256 value)
        public
        virtual
        override(IERC20, ERC20Upgradeable)
        whenNotPaused
        notBlacklisted
        returns (bool)
    {
        require(transferable, "Not transferable");
        require(!blacklisted[from], "from is blacklisted");
        require(getUsableShares(from) >= value, "Insufficient balance");
        return super.transferFrom(from, to, value);
    }

    // @dev get usable shares of the target address
    function getUsableShares(address account) public view returns(uint256) {
        uint256 rawBalance = balanceOf(account);
        uint256 freezed = frozenShares[account];
        uint256 ongoingWithdrawShares = getOngoingWithdrawShares(account);
        // it must be but just check it
        return rawBalance > (freezed + ongoingWithdrawShares) ?
               rawBalance - freezed - ongoingWithdrawShares :
               0;
    }

    // @dev to calculate all the ongoing withdraw amount,
    // include those settled but not finished withdraw requests
    function getOngoingWithdrawShares(address account) public view returns(uint256) {
        uint256 len = _withdrawRequestIds[account].length();
        uint256 shares;
        for (uint256 i = 0; i < len; ) {
            uint128 requestId = uint128(_withdrawRequestIds[account].at(i));
            shares += withdrewRequests[account][requestId].requestShares;
            unchecked { i++; }
        }

        return shares;
    }

    // @dev align the deposit amount decimals to the underlying token decimals
    function alignDepositAmount(uint256 rawAmount, address underlyingToken)
        internal
        view
        returns(uint256)
    {
        if (underlyingToken == underlying) {
            return rawAmount;
        }

        uint256 decimals = underlyingToken == NATIVE_TOKEN ? 18 : IERC20Metadata(underlyingToken).decimals();
        uint256 targetDecimals = underlying == NATIVE_TOKEN ? 18 : IERC20Metadata(underlying).decimals();

        if (decimals > targetDecimals) {
            return rawAmount / 10 ** (decimals - targetDecimals);
        } else if (decimals == targetDecimals) {
            return rawAmount;
        } else {
            return rawAmount * 10 ** (targetDecimals - decimals);
        }
    }

    // @dev deposit underlying asset to the vault, mint shares to the target address
    function deposit(address underlyingToken, uint256 underlyingAmount)
        external
        whenNotPaused
        notBlacklisted
        lock
        payable
    {
        require(acceptUnderlying[underlyingToken] || underlyingToken == underlying || underlyingToken == NATIVE_TOKEN, "not accept underlying");

        (uint256 sharesAmount, uint256 unitNav) = onDepositUnderlying(msg.sender, underlyingToken, underlyingAmount);

        // emit enough information for accounting
        address[] memory p = portfolios();
        uint256[] memory w = weights();
        emit Deposited(
            msg.sender,
            underlyingToken,
            underlyingAmount,
            sharesAmount,
            unitNav,
            settlementPeriod,
            p,
            w,
            block.timestamp
        );
    }

    function _doRequestWithdraw(uint256 shareAmount) internal returns (uint128) {
        require(shareAmount > 0, "share amount is zero");
        uint256 sharesBalance = getUsableShares(msg.sender);
        if (shareAmount != sharesBalance) { // make sure sender can withdraw all shares
            require(shareAmount >= minWithdrawAmount, "withdraw amount too small");
        }
        require(sharesBalance >= shareAmount, "Insufficient balance");

        // to record the request information, merge multiple requests into one request
        uint128 requestId = settlementPeriod;
        _withdrawRequestIds[msg.sender].add(requestId);

        WithdrewRequest storage request = withdrewRequests[msg.sender][requestId];
        request.requestShares += shareAmount;
        request.targetPeriod = requestId;
        request.requestTimestamp = uint64(block.timestamp);
        // to record the total withdraw shares of this period, and sub it while this period is settled
        // so these shares stop yielding
        periodWithdrawShares[requestId] += shareAmount;

        return requestId;
    }

    // @dev request to withdraw shares, it will be executed while current period is settled
    function requestWithdraw(uint256 shareAmount)
        public
        virtual
        whenNotPaused
        notBlacklisted
        lock
        returns (uint128)
    {
        uint128 requestId = _doRequestWithdraw(shareAmount);

        emit WithdrawRequested(
            requestId,
            msg.sender,
            shareAmount,
            block.timestamp
        );

        return requestId;
    }

    // @dev withdraw underlying asset from the vault, burn shares from the target address
    //    only executalbe more than two periods are settled
    //    the requestId is the return value of method `requestWithdraw`
    function withdraw(uint128 requestId)
        public
        virtual
        whenNotPaused
        notBlacklisted
        lock
    {
        uint128 settledPeriod = requestId + 1;
        require(settledPeriod < settlementPeriod, "should wait more than two periods");

        require(_withdrawRequestIds[msg.sender].contains(requestId), "not requested");
        _withdrawRequestIds[msg.sender].remove(requestId);

        WithdrewRequest storage request = withdrewRequests[msg.sender][requestId];
        require(request.requestShares > 0, "no request found");

        require(request.executedTimestamp == 0, "already executed");
        request.executedTimestamp = uint64(block.timestamp);

        unsettledWithdrawShares -= request.requestShares;

        (uint256 underlyingAmount, uint256 unitNav)
            = burnShares(msg.sender, settledPeriod, request.requestShares);
        onWithdrawUnderlying(msg.sender, underlyingAmount);

        emit WithdrawFinished(
            requestId,
            msg.sender,
            request.requestShares,
            unitNav,
            block.timestamp
        );
    }

    // @dev mint shares to the target address, it should be calculated as : shares = amount / unitNav
    // @param to the target address
    // @param underlyingAmount the amount of underlying asset
    function mintShares(address to, uint256 underlyingAmount) internal returns(uint256 sharesAmount, uint256 unitNav) {
        unitNav = getUnitNav(settlementPeriod);
        require(unitNav > 0, "oops: zero unit nav");
        sharesAmount = (underlyingAmount * Precision) / unitNav;

        _mint(to, sharesAmount);
    }

    // @dev burn shares from the target address, it should be calculated as : amount = shares * unitNav
    // @param from the target address
    // @param shares the amount of shares
    function burnShares(address from, uint128 settledPeriod, uint256 sharesAmount) internal returns(uint256, uint256) {
        uint256 unitNav = getUnitNav(settledPeriod);
        require(unitNav > 0, "oops: zero unit nav");
        uint256 amount = (sharesAmount * unitNav) / Precision;
        // burn shares and return the amount of underlying asset
        _burn(from, sharesAmount);
        return (amount, unitNav);
    }
    // @dev get the yield type of the vault
    function getYieldType() public view override returns (YieldType) {
        return yieldType;
    }
    // @dev get portfolios list
    function portfolios() public view returns (address[] memory) {
        return EnumerableSet.values(_portfolios);
    }
    // @dev get weights of the portfolios
    function weights() public view returns (uint256[] memory) {
        uint256 len = _portfolios.length();
        uint256[] memory result = new uint256[](len);
        for (uint256 i = 0; i < len; ) {
            result[i] = portfolioWeights[_portfolios.at(i)];
            unchecked { i++; }
        }
        return result;
    }
    // @dev get current unit nav
    // @param period the period to get the unit nav, period should gte 1
    function getUnitNav(uint128 period) public view returns (uint256) {
        if (period == 0) {
            return 0;
        } else if (period == 1) {
            if (underlying == NATIVE_TOKEN) {
                return 10 ** 18;
            } else {
                IERC20Metadata underlyingToken = IERC20Metadata(underlying);
                return 10 ** underlyingToken.decimals();
            }
        } else {
            return periodUnitNav[period - 1];
        }
    }
}

contracts/vaults/VaultBase.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {YieldType} from "../intf/IVault.sol";

contract VaultBase {
    using EnumerableSet for EnumerableSet.AddressSet;
    using EnumerableSet for EnumerableSet.UintSet;

    uint256 public constant Precision = 10 ** 18; // the precision is the same as decimals

    modifier onlyManager() {
        require(msg.sender == cedefiManager, "Only cedefi manager");
        _;
    }

    modifier lock() {
        require(!_locked, "Locked");
        _locked = true;
        _;
        _locked = false;
    }

    modifier notBlacklisted() {
        require(!blacklisted[msg.sender], "Blacklisted");
        _;
    }

    struct WithdrewRequest {
        uint256 requestShares; // requested shares
        uint128 targetPeriod;  // in which period this withdraw request can be executed;
        uint64  requestTimestamp;      // timestamp of this request, if request many times, only the latest one is recorded
        uint64  executedTimestamp;     // timestamp of this request is executed
    }

    YieldType internal immutable yieldType; // yield type

    /** basic information */
    address public cedefiManager; // admin address, this is creater address of CeDeFi Layer.
    address public underlying; // underlying asset

    /**   Manage information */
    bool private _locked; // locked entrance
    bool public transferable; // the shares are transferable or not
    mapping(address => bool) public blacklisted; // blacklisted users
    mapping(address => uint256) public frozenShares;   // frozen shares
    uint256 public minDepositAmount; // minimum deposit amount
    uint256 public minWithdrawAmount; // maximum withdraw amount

    EnumerableSet.AddressSet internal _portfolios;          // current portfolios
    mapping(address => uint256) public portfolioWeights;    // portfolio -> weight

    uint128 public settlementPeriod; // current settlement period
    mapping(uint128 settlementPeriod => uint256) public periodUnitNav; // settlement period -> unit NAV of each period
    mapping(uint128 settlementPeriod => uint256) public periodWithdrawShares; // settlement period -> total shares  of each period
    uint256 public unsettledWithdrawShares; // total unsettled withdraw shares, someone may request withdraw, but not executed yet

    mapping(address => EnumerableSet.UintSet) internal _withdrawRequestIds; // withdraw request ids
    mapping(address user => mapping(uint128 settlementPeriod => WithdrewRequest)) public withdrewRequests; // user -> settlementPeriod -> withdrew request

    mapping(address => bool) public acceptUnderlying; // accept underlying assets, such as underlying is USD1, and also support USDT, USDC, etc.
    // @dev padding for future upgrade
    uint256[256] private _gap;
}
